mapper.update:
update erp_sales_order
set customer_id = #{customerId}, customer_name = #{customerName}, order_date = #{orderDate},
    delivery_date = #{deliveryDate}, total_qty = #{totalQty}, total_amount = #{totalAmount},
    order_status = #{orderStatus}, update_by = #{updateBy}, update_time = sysdate(), remark = #{remark}
where sales_order_id = #{salesOrderId}
